  initShell:function(){const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.mobile-nav');if(toggle&&nav){toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});document.addEventListener('click',e=>{if(!e.target.closest('.site-header')){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}})}document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>B16.closeModal(b.closest('.modal-wrap'))));document.querySelectorAll('.modal-wrap').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)B16.closeModal(m)}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('.modal-wrap:not([hidden])');if(open)B16.closeModal(open);document.querySelector('.mobile-nav.open')?.classList.remove('open')}})},
